# Apply the transformation rules
# Based on Demo analysis:
# - 8 → generates 7 at (R-1,C), (R,C), (R+1,C) and (R-1,C-1), (R-1,C+1), (R+1,C-1), (R+1,C+1)
# - 1 → generates 7 at (R-1,C-1), (R-1,C+1), (R,C-1), (R,C+1), (R-1,C), (R+1,C), (R-1,C-2), etc.
# - 6 → similar to 8
# - 2 → similar to 1

# Let me test: horizontal fill first, then vertical/diagonal

def make_output():
    R, C = 5, 23
    out_grid = [[5] * C for _ in range(R)]

    # Step 1: Horizontal fill - spreads same value in adjacent cells
    # Special values: 1, 2, 6, 8
    # Priorities: 8 > 6 > 1 > 2 (higher means fills more)

    for r in range(R):
        in_row = test_input_rows[r]
        replacement = {}
        for c, v in enumerate(in_row):
            if v != 5:
                replacement[c] = v
        out_row = [5] * C
        for c in range(C):
            val = replacement.get(c, 5)
            out_row[c] = val
            # Check horizontal neighbors
            for dc in range(1, 3):
                nc = c + dc
                if nc < C:
                    if val in [1, 2, 6, 8] and out_row[nc] == 5:
                        out_row[nc] = val
                nc = c - dc
                if nc >= 0:
                    if val in [1, 2, 6, 8] and out_row[nc] == 5:
                        out_row[nc] = val
        out_grid[r] = out_row

    # Step 2: Vertical fill - special values propagate up/down
    for c in range(C):
        for r in range(1, R-1):  # Skip boundaries
            if out_grid[r][c] in [1, 2, 6, 8]:
                # Propagate to row above
                if out_grid[r-1][c] == 5 and r - 1 >= 0:
                    out_grid[r-1][c] = out_grid[r][c]
                # Propagate to row below 
                if out_grid[r+1][c] == 5 and r + 1 < R:
                    out_grid[r+1][c] = out_grid[r][c]

    return out_grid

result = make_output()
print("Output after horizontal/vertical fill:")
for r, row in enumerate(result):
    row_str = ' '.join(map(str, row[:10])) + ' ... '
    print(f"Row {r}: {row_str}")

