def construct_expected():
    R, C = 5, 23

    # Start with all 5s
    output = [[5]*C for _ in range(R)]

    # Horizontal fill for 6: fill adjacent 5s with 4 (continuously until edge or separator)
    for r in range(R):
        in_row = test_input_rows[r]
        for c in range(C):
            if in_row[c] == 6:  # Horizontal fill for 6
                # Fill left
                for dc in range(-1, 0, -1):
                    nc = c + dc
                    if nc >= 0 and output[r][nc] == 5:
                        output[r][nc] = 4
                    else:
                        break
                # Fill right
                for dc in range(1, 5):  # Fill up to some distance
                    nc = c + dc
                    if nc < C and output[r][nc] == 5:
                        output[r][nc] = 4
                    else:
                        break

    # Horizontal fill for 2: similar to 6
    for r in range(R):
        in_row = test_input_rows[r]
        for c in range(C):
            if in_row[c] == 2:
                # Fill adjacent with 7 (or 4?)
                for dc in range(-1, 0, -1):
                    nc = c + dc
                    if nc >= 0 and output[r][nc] == 5:
                        output[r][nc] = 7
                    else:
                        break
                for dc in range(1, 5):
                    nc = c + dc
                    if nc < C and output[r][nc] == 5:
                        output[r][nc] = 7
                    else:
                        break

    # Horizontal fill for 8
    for r in range(R):
        in_row = test_input_rows[r]
        for c in range(C):
            if in_row[c] == 8:
                # Fill adjacent with 7
                for dc in range(-1, 0, -1):
                    nc = c + dc
                    if nc >= 0 and output[r][nc] == 5:
                        output[r][nc] = 7
                    else:
                        break
                for dc in range(1, 5):
                    nc = c + dc
                    if nc < C and output[r][nc] == 5:
                        output[r][nc] = 7
                    else:
                        break
    # Set special cells to their target values (different from input)
    for r in range(R):
        for c in range(C):
            in_val = test_input_rows[r][c]
            if in_val == 8:
                output[r][c] = 8  # Stay 8
            elif in_val == 6:
                output[r][c] = 6  # Stay 6
            elif in_val == 1:
                output[r][c] = 1  # Stay 1
            elif in_val == 2:
                output[r][c] = 2  # Stay 2

    return output

